const demoRows = [
  { student_id: 'ST-101', cohort: 'Cohort A', activities_planned: 8, activities_completed: 4, learning_outcome_pct: 52, pulse_rating: 3.6 },
  { student_id: 'ST-105', cohort: 'Cohort B', activities_planned: 10, activities_completed: 8, learning_outcome_pct: 78, pulse_rating: 4.1 },
  { student_id: 'ST-108', cohort: 'Cohort B', activities_planned: 6, activities_completed: 2, learning_outcome_pct: 48, pulse_rating: null }
];
const completionThreshold = 65;
const outcomeThreshold = 60;
return demoRows.map((row) => {
  const completion = row.activities_planned ? 100 * row.activities_completed / row.activities_planned : null;
  const flags = [];
  if (completion !== null && completion < completionThreshold) flags.push('completion_below_demo_threshold');
  if (row.learning_outcome_pct !== null && row.learning_outcome_pct < outcomeThreshold) flags.push('outcome_below_demo_threshold');
  if (row.pulse_rating === null) flags.push('pulse_missing');
  return { json: { ...row, completion_pct: completion === null ? null : Math.round(completion * 10) / 10, review_required: flags.length > 0, review_flags: flags, action: flags.length ? 'Human review only; check context with the assigned mentor.' : 'No follow-up flag from demo rules.' } };
});
